INSERT INTO `report_submissions` VALUES (1,1,2,'CWTS masterlist verified with 16 registered students present during orientation.',NULL,NULL,'2026-09-05 12:44:41'),(2,2,4,'ROTC safety and medic personnel assigned for community drill zones.',NULL,NULL,'2026-09-05 12:44:42'),(3,3,3,'LTS student volunteers completed basic life support triage orientation.',NULL,NULL,'2026-09-05 12:44:43'),(4,6,4,'14 cadets mustered with 100% complete uniform accessories and identification cards.',NULL,NULL,'2026-09-05 12:44:45'),(5,7,4,'Cadets achieved satisfactory scores on mechanical training and firearm disassembly/assembly.',NULL,NULL,'2026-09-05 12:44:45'),(6,8,4,'Squad navigation exercises executed smoothly without medical casualties.',NULL,NULL,'2026-09-05 12:44:46'),(7,9,4,'Coastal reconnaissance report compiled with tactical defense logs.',NULL,NULL,'2026-09-05 12:44:47'),(8,12,2,'Completed survey of 120 households; priority identified is coastal waste segregation and youth tutoring.',NULL,NULL,'2026-09-05 12:44:48'),(9,13,2,'Retrieved 34 sacks of non-biodegradable waste in coordination with MENRO Naic.',NULL,NULL,'2026-09-05 12:44:49'),(10,15,3,'Screened 45 pupils across 2 public elementary schools; personalized remedial tutoring modules prepared.',NULL,NULL,'2026-09-05 12:44:50');
