INSERT INTO `reports` VALUES (1,'NSTP 1 Institutional Orientation & Attendance Masterlist','Consolidated attendance report and general student registration roster for the opening plenary orientation of AY 2026-2027.','All','Reviewed','2026-09-15',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:41','2026-09-05 12:44:41'),(2,'Midterm Community Immersion Feasibility & Safety Assessment','Comprehensive risk assessment and safety protocols submission for upcoming fieldwork in partner barangays of Naic.','All','Submitted','2026-10-15',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:42','2026-09-05 12:44:42'),(3,'First Semester Disaster Risk Reduction (DRRM) Training Summary','Documentation and photo narrative of hands-on CPR, fire prevention, and emergency triage drills conducted with Naic MDRRMO.','All','Submitted','2026-11-05',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:43','2026-09-05 12:44:43'),(4,'Form A & Form B Official Master Completion Roll (CHED Endorsement)','Pre-final verification of enrollment numbers, serial IDs, and instructor grade books for CHED and Regional Office submission.','All','Draft','2026-12-10',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:44','2026-09-05 12:44:44'),(5,'NSTP Annual PASS-IN-REVIEW & Culminating Plenary Plan','Program flow, guest dignitaries coordination, and ceremony layout for the joint culmination exercises at the CvSU Naic Gymnasium.','All','Draft','2026-12-18',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:44','2026-09-05 12:44:44'),(6,'ROTC Opening Muster, Formation & Uniform Compliance Audit','First battalion parade muster, headcount verification, and compliance check of cadets with official BDA uniform specifications.','ROTC','Reviewed','2026-09-20',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:44','2026-09-05 12:44:44'),(7,'Marksmanship Fundamentals & Range Safety Compliance Report','Dry-fire rehearsal assessment, weapon handling protocol verification, and safety clearing audit conducted at Naic tactical grounds.','ROTC','Reviewed','2026-10-02',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:45','2026-09-05 12:44:45'),(8,'ROTC Midterm Tactical March & Compass Orienteering Evaluation','Field navigation exercise across designated checkpoints in coastal Naic to test team communication and azimuth compass bearings.','ROTC','Submitted','2026-10-25',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:46','2026-09-05 12:44:46'),(9,'Civil-Military Operations (CMO) Coastal Defense Simulation','Joint simulation drill on shoreline defense, community evacuation assistance, and search-and-rescue communication protocols.','ROTC','Submitted','2026-11-12',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:47','2026-09-05 12:44:47'),(10,'Annual Tactical Inspection (ATI) Rehearsal & Platoon Formations','Full dress rehearsal for the upcoming AFP Reserve Command inspection including manual of arms and military ceremonies.','ROTC','Draft','2026-11-28',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:47','2026-09-05 12:44:47'),(11,'ROTC Commandant Final Cadre Performance & Merit Ratings','Cadet officers and enlisted ranks leadership evaluation, demerit clearance, and final physical fitness test (PFT) scores.','ROTC','Draft','2026-12-15',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:48','2026-09-05 12:44:48'),(12,'CWTS Barangay Community Profiling & Needs Assessment Survey','Comprehensive baseline survey conducted across partner barangays (Bucana Malaki, Halang, Balsahan) on solid waste and health.','CWTS','Reviewed','2026-09-28',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:48','2026-09-05 12:44:48'),(13,'Cavite Shoreline Coastal Cleanup & Waste Segregation Audit','Environmental sanitation drive along Naic coastline resulting in collection and categorization of recyclable and residual plastics.','CWTS','Submitted','2026-10-22',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:49','2026-09-05 12:44:49'),(14,'Community Livelihood Skills Transfer & Organic Composting Workshop','Hands-on livelihood seminar on household container gardening, food preservation, and organic enzyme composting for mothers.','CWTS','Draft','2026-11-20',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:50','2026-09-05 12:44:50'),(15,'Adopted Elementary School Reading Literacy Screening & Diagnostic Portfolio','Pre-test reading assessment of Grade 2 and 3 pupils in partner public schools using Phil-IRI diagnostic reading tools.','LTS','Submitted','2026-10-18',1,'2026-2027 1st Semester',NULL,NULL,'2026-09-05 12:44:50','2026-09-05 12:44:50'),(18,'Testing','','All','Draft','2026-10-30',1,'2026-2027 1st Semester',NULL,NULL,'2026-10-13 22:49:11','2026-10-13 22:49:11');
